-- 175: Original BrillaPrep WASSCE BrillaPrep transitional Metalwork beta content blueprint questions, part 4.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_175_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_175_guard;
INSERT INTO _migration_175_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_metalwork_b003_016' AND NOT (q.topic_id IS 'topic_was_metalwork_b003_4' AND q.subject_id IS 'subj_wassce_metalwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is a development in sheet-metal work?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A heat-treatment hardness graph","B. A finished screw thread profile","C. A machine-foundation drawing only","D. A flat pattern that forms the required three-dimensional shape"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The development establishes true sizes and seam allowances before cutting so the folded or rolled sheet reaches its intended form. Therefore the correct answer is D: A flat pattern that forms the required three-dimensional shape.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_metalwork_b003_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_metalwork_b003_016' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Metalwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_175_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_metalwork_b003_017' AND NOT (q.topic_id IS 'topic_was_metalwork_b003_4' AND q.subject_id IS 'subj_wassce_metalwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is bend allowance included when marking a sheet-metal component?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Material occupies length through the bend radius","B. Every bend removes all material at the corner","C. The allowance compensates only for paint thickness","D. It prevents any elastic recovery after bending"]' AND q.correct_answer IS 'A' AND q.explanation IS 'The neutral layer retains length through the bend, so the flat blank must include an allowance based on angle, radius and material thickness. Therefore the correct answer is A: Material occupies length through the bend radius.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_metalwork_b003_4' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_metalwork_b003_017' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Metalwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_175_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_metalwork_b003_018' AND NOT (q.topic_id IS 'topic_was_metalwork_b003_4' AND q.subject_id IS 'subj_wassce_metalwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which seam provides a secure longitudinal joint on a light sheet-metal cylinder?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A plain butt edge without joining","B. A grooved seam","C. A wood dovetail joint","D. A countersunk hole without a fastener"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Interlocked folded edges closed with a groover create a mechanically secure sheet seam suitable for many cylindrical products. Therefore the correct answer is B: A grooved seam.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_metalwork_b003_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_metalwork_b003_018' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Metalwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_175_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_metalwork_b003_019' AND NOT (q.topic_id IS 'topic_was_metalwork_b003_4' AND q.subject_id IS 'subj_wassce_metalwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the purpose of a stake in sheet-metal work?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Cut threads in round bar","B. Measure electrical current","C. Support the sheet while forming particular curves and edges","D. Harden the entire sheet by quenching"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Stakes provide shaped working surfaces over which sheet is bent, planished or seamed without damaging the required form. Therefore the correct answer is C: Support the sheet while forming particular curves and edges.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_metalwork_b003_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_metalwork_b003_019' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Metalwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_175_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_metalwork_b003_020' AND NOT (q.topic_id IS 'topic_was_metalwork_b003_4' AND q.subject_id IS 'subj_wassce_metalwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why are notches cut at selected corners before folding a sheet-metal tray?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Increase the blank size after cutting","B. Remove the need for all edge seams","C. Make every corner completely rounded","D. Prevent overlapping excess material and permit clean corner formation"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Proper notch geometry removes material that would collide during folding while preserving tabs or allowances needed to join the corner. Therefore the correct answer is D: Prevent overlapping excess material and permit clean corner formation.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_metalwork_b003_4' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_metalwork_b003_020' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Metalwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
